-- CreateEnum: TaskSharePermission
CREATE TYPE "TaskSharePermission" AS ENUM ('VIEW', 'COMMENT', 'EDIT');

-- CreateTable: TaskComment
CREATE TABLE "task_comments" (
    "id" TEXT NOT NULL,
    "taskId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "content" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "editedAt" TIMESTAMP(3),

    CONSTRAINT "task_comments_pkey" PRIMARY KEY ("id")
);

-- CreateTable: TaskActivity
CREATE TABLE "task_activities" (
    "id" TEXT NOT NULL,
    "taskId" TEXT NOT NULL,
    "userId" TEXT,
    "action" TEXT NOT NULL,
    "details" JSONB,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "task_activities_pkey" PRIMARY KEY ("id")
);

-- CreateTable: TaskShare
CREATE TABLE "task_shares" (
    "id" TEXT NOT NULL,
    "taskId" TEXT NOT NULL,
    "sharedWithUserId" TEXT NOT NULL,
    "permissions" "TaskSharePermission" NOT NULL DEFAULT 'VIEW',
    "sharedByUserId" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "task_shares_pkey" PRIMARY KEY ("id")
);

-- AlterTable: Add assignedUserId to tasks
ALTER TABLE "tasks" ADD COLUMN "assignedUserId" TEXT;

-- CreateIndex: TaskComment indexes
CREATE INDEX "task_comments_taskId_idx" ON "task_comments"("taskId");
CREATE INDEX "task_comments_taskId_createdAt_idx" ON "task_comments"("taskId", "createdAt");
CREATE INDEX "task_comments_userId_idx" ON "task_comments"("userId");

-- CreateIndex: TaskActivity indexes
CREATE INDEX "task_activities_taskId_idx" ON "task_activities"("taskId");
CREATE INDEX "task_activities_taskId_createdAt_idx" ON "task_activities"("taskId", "createdAt");
CREATE INDEX "task_activities_userId_idx" ON "task_activities"("userId");

-- CreateIndex: TaskShare indexes
CREATE UNIQUE INDEX "task_shares_taskId_sharedWithUserId_key" ON "task_shares"("taskId", "sharedWithUserId");
CREATE INDEX "task_shares_taskId_idx" ON "task_shares"("taskId");
CREATE INDEX "task_shares_sharedWithUserId_idx" ON "task_shares"("sharedWithUserId");
CREATE INDEX "task_shares_sharedWithUserId_permissions_idx" ON "task_shares"("sharedWithUserId", "permissions");

-- CreateIndex: Task assignedUserId index
CREATE INDEX "tasks_assignedUserId_idx" ON "tasks"("assignedUserId");

-- AddForeignKey: TaskComment to Task
ALTER TABLE "task_comments" ADD CONSTRAINT "task_comments_taskId_fkey" FOREIGN KEY ("taskId") REFERENCES "tasks"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: TaskComment to User
ALTER TABLE "task_comments" ADD CONSTRAINT "task_comments_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: TaskActivity to Task
ALTER TABLE "task_activities" ADD CONSTRAINT "task_activities_taskId_fkey" FOREIGN KEY ("taskId") REFERENCES "tasks"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: TaskActivity to User (nullable)
ALTER TABLE "task_activities" ADD CONSTRAINT "task_activities_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey: TaskShare to Task
ALTER TABLE "task_shares" ADD CONSTRAINT "task_shares_taskId_fkey" FOREIGN KEY ("taskId") REFERENCES "tasks"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: TaskShare to User (sharedWith)
ALTER TABLE "task_shares" ADD CONSTRAINT "task_shares_sharedWithUserId_fkey" FOREIGN KEY ("sharedWithUserId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey: TaskShare to User (sharedBy)
ALTER TABLE "task_shares" ADD CONSTRAINT "task_shares_sharedByUserId_fkey" FOREIGN KEY ("sharedByUserId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

