ALTER TABLE "tasks" ADD CONSTRAINT "tasks_assignedUserId_fkey" FOREIGN KEY ("assignedUserId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Update User relation names (need to drop and recreate)
-- First, drop existing foreign key
ALTER TABLE "tasks" DROP CONSTRAINT IF EXISTS "tasks_userId_fkey";

-- Recreate with named relation
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
